export const FX_GLSL_BASELINE_HASH =
  "\nfloat fxHash1(float n){float s=sin(n*127.1)*43758.5453123;return s-floor(s);}\nfloat fxHash2(vec2 p){p=fract(p*vec2(123.34,456.21));p+=dot(p,p+45.32);return fract(p.x*p.y);}\nfloat fxHash3(vec3 p){p=fract(p*vec3(443.897,441.423,437.195));p+=dot(p,p.yzx+19.19);return fract((p.x+p.y)*p.z);}\nvec2 fxHash22(vec2 p){vec3 q=fract(p.xyx*vec3(0.1031,0.1030,0.0973));q+=dot(q,q.yzx+33.33);return fract((q.xx+q.yz)*q.zy);}\nvec3 fxHash33(vec3 p){p=fract(p*vec3(0.1031,0.1030,0.0973));p+=dot(p,p.yxz+33.33);return fract((p.xxy+p.yxx)*p.zyx);}\nvec4 fxHash44(vec4 p){p=fract(p*vec4(0.1031,0.1030,0.0973,0.1099));p+=dot(p,p.wzxy+33.33);return fract((p.xxyz+p.yzzw)*p.zywx);}";

export const FX_GLSL_STANDARD_HASH =
  "\nuint fxPcg(uint v){uint s=v*747796405u+2891336453u;uint w=((s>>((s>>28u)+4u))^s)*277803737u;return (w>>22u)^w;}\nfloat fxUnit(uint h){return float(h>>8u)*5.960464477539063e-8;}\nvec2 fxUnit2(uint h){return vec2(h>>16u,h&65535u)*1.52587890625e-5;}\nvec3 fxUnit3(uint h){return vec3(h>>22u,(h>>11u)&2047u,h&2047u)*vec3(9.765625e-4,4.8828125e-4,4.8828125e-4);}\nuint fxLattice(uvec3 c){return c.x*73856093u^c.y*19349663u^c.z*83492791u;}";

export const FX_GLSL_BASELINE_NOISE =
  "\nfloat noise(float p){float fl=floor(p);float f=p-fl;float u=f*f*(3.0-2.0*f);float c0=fxHash1(fl+0.0);float c1=fxHash1(fl+1.0);return mix(c0,c1,u)*2.0-1.0;}\nfloat noise(vec2 p){vec2 fl=floor(p);vec2 f=p-fl;vec2 u=f*f*(3.0-2.0*f);float c0=fxHash2(fl+vec2(0.0,0.0));float c1=fxHash2(fl+vec2(1.0,0.0));float c2=fxHash2(fl+vec2(0.0,1.0));float c3=fxHash2(fl+vec2(1.0,1.0));return mix(mix(c0,c1,u.x),mix(c2,c3,u.x),u.y)*2.0-1.0;}\nfloat noise(vec3 p){vec3 fl=floor(p);vec3 f=p-fl;vec3 u=f*f*(3.0-2.0*f);float c0=fxHash3(fl+vec3(0.0,0.0,0.0));float c1=fxHash3(fl+vec3(1.0,0.0,0.0));float c2=fxHash3(fl+vec3(0.0,1.0,0.0));float c3=fxHash3(fl+vec3(1.0,1.0,0.0));float c4=fxHash3(fl+vec3(0.0,0.0,1.0));float c5=fxHash3(fl+vec3(1.0,0.0,1.0));float c6=fxHash3(fl+vec3(0.0,1.0,1.0));float c7=fxHash3(fl+vec3(1.0,1.0,1.0));return mix(mix(mix(c0,c1,u.x),mix(c2,c3,u.x),u.y),mix(mix(c4,c5,u.x),mix(c6,c7,u.x),u.y),u.z)*2.0-1.0;}";

export const FX_GLSL_STANDARD_NOISE =
  "\nfloat noise(float p){float fl=floor(p);float f=p-fl;float u=f*f*(3.0-2.0*f);uint l0=uint(int(fl));uint l1=l0+1u;float c0=fxUnit(fxPcg(l0));float c1=fxUnit(fxPcg(l1));return mix(c0,c1,u)*2.0-1.0;}\nfloat noise(vec2 p){vec2 fl=floor(p);vec2 f=p-fl;vec2 u=f*f*(3.0-2.0*f);uvec2 l0=uvec2(ivec2(fl))*uvec2(73856093u,19349663u);uvec2 l1=l0+uvec2(73856093u,19349663u);float c0=fxUnit(fxPcg(l0.x^l0.y));float c1=fxUnit(fxPcg(l1.x^l0.y));float c2=fxUnit(fxPcg(l0.x^l1.y));float c3=fxUnit(fxPcg(l1.x^l1.y));return mix(mix(c0,c1,u.x),mix(c2,c3,u.x),u.y)*2.0-1.0;}\nfloat noise(vec3 p){vec3 fl=floor(p);vec3 f=p-fl;vec3 u=f*f*(3.0-2.0*f);uvec3 l0=uvec3(ivec3(fl))*uvec3(73856093u,19349663u,83492791u);uvec3 l1=l0+uvec3(73856093u,19349663u,83492791u);float c0=fxUnit(fxPcg(l0.x^l0.y^l0.z));float c1=fxUnit(fxPcg(l1.x^l0.y^l0.z));float c2=fxUnit(fxPcg(l0.x^l1.y^l0.z));float c3=fxUnit(fxPcg(l1.x^l1.y^l0.z));float c4=fxUnit(fxPcg(l0.x^l0.y^l1.z));float c5=fxUnit(fxPcg(l1.x^l0.y^l1.z));float c6=fxUnit(fxPcg(l0.x^l1.y^l1.z));float c7=fxUnit(fxPcg(l1.x^l1.y^l1.z));return mix(mix(mix(c0,c1,u.x),mix(c2,c3,u.x),u.y),mix(mix(c4,c5,u.x),mix(c6,c7,u.x),u.y),u.z)*2.0-1.0;}";

export const FX_GLSL_BASELINE_NOISED =
  "\nvec3 fxNoised(vec2 p){vec2 fl=floor(p);vec2 f=p-fl;vec2 u=f*f*(3.0-2.0*f);float c0=fxHash2(fl+vec2(0.0,0.0));float c1=fxHash2(fl+vec2(1.0,0.0));float c2=fxHash2(fl+vec2(0.0,1.0));float c3=fxHash2(fl+vec2(1.0,1.0));vec2 du=6.0*f*(1.0-f);float k1=c1-c0;float k2=c2-c0;float k3=c0-c1-c2+c3;float v=c0+k1*u.x+k2*u.y+k3*u.x*u.y;vec2 g=du*vec2(k1+k3*u.y,k2+k3*u.x);return vec3(v*2.0-1.0,g*2.0);}\nvec4 fxNoised(vec3 p){vec3 fl=floor(p);vec3 f=p-fl;vec3 u=f*f*(3.0-2.0*f);float c0=fxHash3(fl+vec3(0.0,0.0,0.0));float c1=fxHash3(fl+vec3(1.0,0.0,0.0));float c2=fxHash3(fl+vec3(0.0,1.0,0.0));float c3=fxHash3(fl+vec3(1.0,1.0,0.0));float c4=fxHash3(fl+vec3(0.0,0.0,1.0));float c5=fxHash3(fl+vec3(1.0,0.0,1.0));float c6=fxHash3(fl+vec3(0.0,1.0,1.0));float c7=fxHash3(fl+vec3(1.0,1.0,1.0));vec3 du=6.0*f*(1.0-f);float k1=c1-c0;float k2=c2-c0;float k3=c4-c0;float k4=c0-c1-c2+c3;float k5=c0-c2-c4+c6;float k6=c0-c1-c4+c5;float k7=-c0+c1+c2-c3+c4-c5-c6+c7;float v=c0+k1*u.x+k2*u.y+k3*u.z+k4*u.x*u.y+k5*u.y*u.z+k6*u.z*u.x+k7*u.x*u.y*u.z;vec3 g=du*vec3(k1+k4*u.y+k6*u.z+k7*u.y*u.z,k2+k5*u.z+k4*u.x+k7*u.z*u.x,k3+k6*u.x+k5*u.y+k7*u.x*u.y);return vec4(v*2.0-1.0,g*2.0);}";

export const FX_GLSL_STANDARD_NOISED =
  "\nvec3 fxNoised(vec2 p){vec2 fl=floor(p);vec2 f=p-fl;vec2 u=f*f*(3.0-2.0*f);uvec2 l0=uvec2(ivec2(fl))*uvec2(73856093u,19349663u);uvec2 l1=l0+uvec2(73856093u,19349663u);float c0=fxUnit(fxPcg(l0.x^l0.y));float c1=fxUnit(fxPcg(l1.x^l0.y));float c2=fxUnit(fxPcg(l0.x^l1.y));float c3=fxUnit(fxPcg(l1.x^l1.y));vec2 du=6.0*f*(1.0-f);float k1=c1-c0;float k2=c2-c0;float k3=c0-c1-c2+c3;float v=c0+k1*u.x+k2*u.y+k3*u.x*u.y;vec2 g=du*vec2(k1+k3*u.y,k2+k3*u.x);return vec3(v*2.0-1.0,g*2.0);}\nvec4 fxNoised(vec3 p){vec3 fl=floor(p);vec3 f=p-fl;vec3 u=f*f*(3.0-2.0*f);uvec3 l0=uvec3(ivec3(fl))*uvec3(73856093u,19349663u,83492791u);uvec3 l1=l0+uvec3(73856093u,19349663u,83492791u);float c0=fxUnit(fxPcg(l0.x^l0.y^l0.z));float c1=fxUnit(fxPcg(l1.x^l0.y^l0.z));float c2=fxUnit(fxPcg(l0.x^l1.y^l0.z));float c3=fxUnit(fxPcg(l1.x^l1.y^l0.z));float c4=fxUnit(fxPcg(l0.x^l0.y^l1.z));float c5=fxUnit(fxPcg(l1.x^l0.y^l1.z));float c6=fxUnit(fxPcg(l0.x^l1.y^l1.z));float c7=fxUnit(fxPcg(l1.x^l1.y^l1.z));vec3 du=6.0*f*(1.0-f);float k1=c1-c0;float k2=c2-c0;float k3=c4-c0;float k4=c0-c1-c2+c3;float k5=c0-c2-c4+c6;float k6=c0-c1-c4+c5;float k7=-c0+c1+c2-c3+c4-c5-c6+c7;float v=c0+k1*u.x+k2*u.y+k3*u.z+k4*u.x*u.y+k5*u.y*u.z+k6*u.z*u.x+k7*u.x*u.y*u.z;vec3 g=du*vec3(k1+k4*u.y+k6*u.z+k7*u.y*u.z,k2+k5*u.z+k4*u.x+k7*u.z*u.x,k3+k6*u.x+k5*u.y+k7*u.x*u.y);return vec4(v*2.0-1.0,g*2.0);}";

export const FX_GLSL_FBM =
  "\nfloat fxFbm(float p,float octaves,float lacunarity,float gain){int n=int(clamp(floor(octaves),0.0,8.0));float sum=float(0.0);float amp=1.0;float total=0.0;for(int o=0;o<8;o++){if(o>=n)break;sum+=noise(p)*amp;total+=amp;amp*=gain;p=p*lacunarity+7.31;}return total>0.0?sum/total:float(0.0);}\nfloat fxFbm(vec2 p,float octaves,float lacunarity,float gain){int n=int(clamp(floor(octaves),0.0,8.0));float sum=float(0.0);float amp=1.0;float total=0.0;for(int o=0;o<8;o++){if(o>=n)break;sum+=noise(p)*amp;total+=amp;amp*=gain;p=p*lacunarity+7.31;}return total>0.0?sum/total:float(0.0);}\nfloat fxFbm(vec3 p,float octaves,float lacunarity,float gain){int n=int(clamp(floor(octaves),0.0,8.0));float sum=float(0.0);float amp=1.0;float total=0.0;for(int o=0;o<8;o++){if(o>=n)break;sum+=noise(p)*amp;total+=amp;amp*=gain;p=p*lacunarity+7.31;}return total>0.0?sum/total:float(0.0);}";

