export const FX_GLSL_BASELINE_SEED_HASH =
  "\nfloat fxSeedHash1(vec3 s,float salt){return fxHash44(vec4(s,salt)).x;}\nvec2 fxSeedHash2(vec3 s,float salt){return fxHash44(vec4(s,salt)).xy;}\nvec3 fxSeedHash3(vec3 s,float salt){return fxHash44(vec4(s,salt)).xyz;}\nvec4 fxSeedHash4(vec3 s,float salt){return fxHash44(vec4(s,salt)).xyzw;}";

export const FX_GLSL_STANDARD_SEED_HASH =
  "\nfloat fxSeedHash1(vec3 s,float salt){uint h0=fxPcg(fxLattice(floatBitsToUint(s))^fxPcg(floatBitsToUint(salt)));return fxUnit(h0);}\nvec2 fxSeedHash2(vec3 s,float salt){uint h0=fxPcg(fxLattice(floatBitsToUint(s))^fxPcg(floatBitsToUint(salt)));uint h1=fxPcg(h0);return vec2(fxUnit(h0),fxUnit(h1));}\nvec3 fxSeedHash3(vec3 s,float salt){uint h0=fxPcg(fxLattice(floatBitsToUint(s))^fxPcg(floatBitsToUint(salt)));uint h1=fxPcg(h0);uint h2=fxPcg(h1);return vec3(fxUnit(h0),fxUnit(h1),fxUnit(h2));}\nvec4 fxSeedHash4(vec3 s,float salt){uint h0=fxPcg(fxLattice(floatBitsToUint(s))^fxPcg(floatBitsToUint(salt)));uint h1=fxPcg(h0);uint h2=fxPcg(h1);uint h3=fxPcg(h2);return vec4(fxUnit(h0),fxUnit(h1),fxUnit(h2),fxUnit(h3));}";

export const FX_GLSL_TRANSPOSE =
  "\nmat2 fxTranspose(mat2 m){return mat2(m[0][0],m[1][0],m[0][1],m[1][1]);}\nmat3 fxTranspose(mat3 m){return mat3(m[0][0],m[1][0],m[2][0],m[0][1],m[1][1],m[2][1],m[0][2],m[1][2],m[2][2]);}\nmat4 fxTranspose(mat4 m){return mat4(\n  m[0][0],m[1][0],m[2][0],m[3][0],\n  m[0][1],m[1][1],m[2][1],m[3][1],\n  m[0][2],m[1][2],m[2][2],m[3][2],\n  m[0][3],m[1][3],m[2][3],m[3][3]);}";

export const FX_GLSL_DETERMINANT =
  "\nfloat fxDeterminant(mat2 m){return m[0][0]*m[1][1]-m[0][1]*m[1][0];}\nfloat fxDeterminant(mat3 m){\n  return m[0][0]*(m[1][1]*m[2][2]-m[2][1]*m[1][2])\n        -m[1][0]*(m[0][1]*m[2][2]-m[2][1]*m[0][2])\n        +m[2][0]*(m[0][1]*m[1][2]-m[1][1]*m[0][2]);}\nfloat fxDeterminant(mat4 m){\n  float b00=m[0][0]*m[1][1]-m[0][1]*m[1][0];\n  float b01=m[0][0]*m[1][2]-m[0][2]*m[1][0];\n  float b02=m[0][0]*m[1][3]-m[0][3]*m[1][0];\n  float b03=m[0][1]*m[1][2]-m[0][2]*m[1][1];\n  float b04=m[0][1]*m[1][3]-m[0][3]*m[1][1];\n  float b05=m[0][2]*m[1][3]-m[0][3]*m[1][2];\n  float b06=m[2][0]*m[3][1]-m[2][1]*m[3][0];\n  float b07=m[2][0]*m[3][2]-m[2][2]*m[3][0];\n  float b08=m[2][0]*m[3][3]-m[2][3]*m[3][0];\n  float b09=m[2][1]*m[3][2]-m[2][2]*m[3][1];\n  float b10=m[2][1]*m[3][3]-m[2][3]*m[3][1];\n  float b11=m[2][2]*m[3][3]-m[2][3]*m[3][2];\n  return b00*b11-b01*b10+b02*b09+b03*b08-b04*b07+b05*b06;}";

export const FX_GLSL_INVERSE =
  "\nmat2 fxInverse(mat2 m){\n  return mat2(m[1][1],-m[0][1],-m[1][0],m[0][0])/(m[0][0]*m[1][1]-m[0][1]*m[1][0]);}\nmat3 fxInverse(mat3 m){\n  float a00=m[0][0],a01=m[0][1],a02=m[0][2];\n  float a10=m[1][0],a11=m[1][1],a12=m[1][2];\n  float a20=m[2][0],a21=m[2][1],a22=m[2][2];\n  float b01=a22*a11-a12*a21;\n  float b11=-a22*a10+a12*a20;\n  float b21=a21*a10-a11*a20;\n  float det=a00*b01+a01*b11+a02*b21;\n  return mat3(b01,(-a22*a01+a02*a21),(a12*a01-a02*a11),\n              b11,(a22*a00-a02*a20),(-a12*a00+a02*a10),\n              b21,(-a21*a00+a01*a20),(a11*a00-a01*a10))/det;}\nmat4 fxInverse(mat4 m){\n  float a00=m[0][0],a01=m[0][1],a02=m[0][2],a03=m[0][3];\n  float a10=m[1][0],a11=m[1][1],a12=m[1][2],a13=m[1][3];\n  float a20=m[2][0],a21=m[2][1],a22=m[2][2],a23=m[2][3];\n  float a30=m[3][0],a31=m[3][1],a32=m[3][2],a33=m[3][3];\n  float b00=a00*a11-a01*a10;\n  float b01=a00*a12-a02*a10;\n  float b02=a00*a13-a03*a10;\n  float b03=a01*a12-a02*a11;\n  float b04=a01*a13-a03*a11;\n  float b05=a02*a13-a03*a12;\n  float b06=a20*a31-a21*a30;\n  float b07=a20*a32-a22*a30;\n  float b08=a20*a33-a23*a30;\n  float b09=a21*a32-a22*a31;\n  float b10=a21*a33-a23*a31;\n  float b11=a22*a33-a23*a32;\n  float det=b00*b11-b01*b10+b02*b09+b03*b08-b04*b07+b05*b06;\n  return mat4(\n    a11*b11-a12*b10+a13*b09, a02*b10-a01*b11-a03*b09, a31*b05-a32*b04+a33*b03, a22*b04-a21*b05-a23*b03,\n    a12*b08-a10*b11-a13*b07, a00*b11-a02*b08+a03*b07, a32*b02-a30*b05-a33*b01, a20*b05-a22*b02+a23*b01,\n    a10*b10-a11*b08+a13*b06, a01*b08-a00*b10-a03*b06, a30*b04-a31*b02+a33*b00, a21*b02-a20*b04-a23*b00,\n    a11*b07-a10*b09-a12*b06, a00*b09-a01*b07+a02*b06, a31*b01-a30*b03-a32*b00, a20*b03-a21*b01+a22*b00)/det;}";

export const FX_GLSL_RAND =
  "\nint fxRandCounter = 0;\nfloat fxNextRandom(){\n  fxRandCounter+=1;\n  return fxUnit(fxPcg(fxLattice(uvec3(uint(gl_VertexID),uint(u_fxRandSeed),uint(fxRandCounter)))));\n}";

export const FX_GLSL_MESH_FETCH =
  "vec4 fxMeshFetch(sampler2D table, float texel) {\n  int index = int(texel);\n  int width = textureSize(table, 0).x;\n  return texelFetch(table, ivec2(index % width, index / width), 0);\n}";

export const FX_GLSL_SCENE_DEPTH_CONTACT =
  "vec3 fxSceneDepthPoint(vec2 uv) {\n  vec4 point = u_fxInverseViewProjection * vec4(vec3(uv, texture(u_fxSceneDepth, uv).r) * 2.0 - 1.0, 1.0);\n  return point.xyz / point.w;\n}\nvec4 fxSceneDepthContact(vec3 position, float thickness) {\n  vec4 none = vec4(0.0, 1.0, 0.0, 1000000.0);\n  if (u_fxSceneDepthFrame.z == 0.0) {\n    return none;\n  }\n  vec4 clip = u_fxViewProjection * vec4(position, 1.0);\n  if (clip.w <= 0.0 || any(greaterThan(abs(clip.xy), vec2(clip.w)))) {\n    return none;\n  }\n  vec2 uv = clip.xy / clip.w * 0.5 + 0.5;\n  if (texture(u_fxSceneDepth, uv).r >= 1.0) {\n    return none;\n  }\n  vec2 texel = u_fxSceneDepthFrame.xy;\n  vec3 center = fxSceneDepthPoint(uv);\n  vec3 right = fxSceneDepthPoint(uv + vec2(texel.x, 0.0)) - center;\n  vec3 left = center - fxSceneDepthPoint(uv - vec2(texel.x, 0.0));\n  vec3 up = fxSceneDepthPoint(uv + vec2(0.0, texel.y)) - center;\n  vec3 down = center - fxSceneDepthPoint(uv - vec2(0.0, texel.y));\n  vec3 normal = cross(dot(right, right) < dot(left, left) ? right : left, dot(up, up) < dot(down, down) ? up : down);\n  float area = length(normal);\n  if (area == 0.0) {\n    return none;\n  }\n  vec4 near = u_fxInverseViewProjection * vec4(uv * 2.0 - 1.0, -1.0, 1.0);\n  normal /= dot(normal, near.xyz / near.w - center) < 0.0 ? -area : area;\n  float distance = dot(position - center, normal);\n  return distance < -thickness ? none : vec4(normal, distance);\n}";

export const FX_GLSL_BLEND_NORMAL =
  "vec4 fxBlendNormal(vec4 base, vec4 blend) {\n  float a = blend.a + base.a * (1.0 - blend.a);\n  vec3 rgb = (blend.rgb * blend.a + base.rgb * base.a * (1.0 - blend.a)) / max(a, 1e-4);\n  return vec4(rgb, a);\n}";

export const FX_GLSL_SPHERICAL_CLIP =
  "vec4 fxApplySphericalClip(vec2 uv, float innerRadius) {\n  float distanceToCenter = distance(uv, vec2(0.5, 0.5));\n  return vec4(1.0, 1.0, 1.0, 1.0 - smoothstep(innerRadius, 0.5, distanceToCenter));\n}";

export const FX_GLSL_LIGHTNESS_BLENDING_MASK =
  "float fxLightnessBlendingMask(vec4 color, float edge0, float edge1) {\n  float brightness = dot(color.rgb, vec3(0.2126, 0.7152, 0.0722));\n  return smoothstep(edge0, max(edge1, edge0 + 1e-4), brightness);\n}";

export const FX_GLSL_TANGENT_TO_WORLD_NORMAL =
  "vec3 fxTangentToWorldNormal(vec3 tangentNormal, vec3 n, vec3 t) {\n  vec3 N = normalize(n);\n  vec3 T = normalize(t - N * dot(N, t));\n  vec3 B = cross(N, T);\n  return normalize(mat3(T, B, N) * tangentNormal);\n}";

export const FX_GLSL_SPHERICAL_NORMAL =
  "vec3 fxComputeSphericalNormal(vec2 uv) {\n  vec2 centeredUV = uv * 2.0 - 1.0;\n  return normalize(vec3(centeredUV, sqrt(max(0.0, 1.0 - dot(centeredUV, centeredUV)))));\n}";

export const FX_GLSL_UNPACK_NORMAL =
  "vec3 fxUnpackNormal(vec4 c, float strength) {\n  vec3 n = c.rgb * 2.0 - 1.0;\n  n.xy *= strength;\n  return n;\n}";

export const FX_GLSL_FLIPBOOK_FRAME_ONCE =
  "vec3 fxAnimatedFrameOnce(float ratio, float totalFrames) {\n  float framePos = clamp(ratio, 0.0, 1.0) * totalFrames;\n  float last = totalFrames - 1.0;\n  float frame = min(floor(framePos), last);\n  return vec3(frame, min(frame + 1.0, last), framePos - frame);\n}";

export const FX_GLSL_FLIPBOOK_FRAME_LOOP =
  "vec3 fxAnimatedFrameLoop(float ratio, float totalFrames) {\n  float framePos = fract(ratio) * totalFrames;\n  float frame = floor(framePos);\n  return vec3(frame, mod(frame + 1.0, totalFrames), framePos - frame);\n}";

export const FX_GLSL_FLIPBOOK_FRAME_UV =
  "vec2 fxFlipbookFrameUV(vec2 uv, float frame, float columns, float rows) {\n  float row = floor((frame + 0.5) / columns);\n  float column = frame - row * columns;\n  return vec2((column + uv.x) / columns, 1.0 - (row + 1.0 - uv.y) / rows);\n}";

/** The name of a GLSL helper's constant. */
export type FXGLSLHelperName =
  | "FX_GLSL_BASELINE_HASH"
  | "FX_GLSL_STANDARD_HASH"
  | "FX_GLSL_BASELINE_NOISE"
  | "FX_GLSL_STANDARD_NOISE"
  | "FX_GLSL_BASELINE_NOISED"
  | "FX_GLSL_STANDARD_NOISED"
  | "FX_GLSL_FBM"
  | "FX_GLSL_FBM_OCTAVES_1"
  | "FX_GLSL_CURL_OCTAVES_1"
  | "FX_GLSL_FBM_OCTAVES_2"
  | "FX_GLSL_CURL_OCTAVES_2"
  | "FX_GLSL_FBM_OCTAVES_3"
  | "FX_GLSL_CURL_OCTAVES_3"
